def count_up_to(n: int) -> list[int]:
    """Return the list of primes strictly less than n."""
    if n <= 2:
        return []
    sieve: list[bool] = [True] * n
    sieve[0] = False
    sieve[1] = False
    i = 2
    while i * i < n:
        if sieve[i]:
            for j in range(i * i, n, i):
                sieve[j] = False
        i += 1
    return [k for k in range(2, n) if sieve[k]]

