def unique_digits(x: list[int]) -> list[int]:
    """Given a list of positive integers x. return a sorted list of all 
    elements that hasn't any even digit.

    Note: Returned list should be sorted in increasing order.

    For example:
    >>> unique_digits([15, 33, 1422, 1])
    [1, 15, 33]
    >>> unique_digits([152, 323, 1422, 10])
    []
    """
    def all_odd(n: int) -> bool:
        return all(int(d) % 2 == 1 for d in str(abs(n)))

    return sorted(n for n in x if all_odd(n))

def get_max_triples(n: int) -> int:
    """
    Count triples i<j<k of a[i] = i*i - i + 1 whose sum is divisible by 3.
    """
    counts = [0, 0, 0]
    for i in range(1, n + 1):
        counts[(i * i - i + 1) % 3] += 1

    def comb3(m: int) -> int:
        return m * (m - 1) * (m - 2) // 6

    # Residues sum to 0 mod 3: (0,0,0), (1,1,1), (2,2,2), or (0,1,2)
    return (
        comb3(counts[0])
        + comb3(counts[1])
        + comb3(counts[2])
        + counts[0] * counts[1] * counts[2]
    )

