def do_algebra(operator: list[str], operand: list[int]) -> int:
    """
    Build and evaluate an algebraic expression from operators and operands,
    respecting standard precedence (** > * and // > + and -).
    """
    allowed = {"+", "-", "*", "//", "**"}
    if len(operator) != len(operand) - 1:
        raise ValueError("operator list must be one shorter than operand list")
    for op in operator:
        if op not in allowed:
            raise ValueError(f"unsupported operator: {op}")

    nums: list[int] = [int(n) for n in operand]
    ops: list[str] = list(operator)

    # Exponentiation: right-associative, so process from right to left.
    i = len(ops) - 1
    while i >= 0:
        if ops[i] == "**":
            nums[i] = nums[i] ** nums[i + 1]
            del nums[i + 1]
            del ops[i]
        i -= 1

    # Multiplication and floor division: left-associative.
    i = 0
    while i < len(ops):
        if ops[i] == "*":
            nums[i] = nums[i] * nums[i + 1]
            del nums[i + 1]
            del ops[i]
        elif ops[i] == "//":
            nums[i] = nums[i] // nums[i + 1]
            del nums[i + 1]
            del ops[i]
        else:
            i += 1

    # Addition and subtraction: left-associative.
    result: int = nums[0]
    for op, num in zip(ops, nums[1:]):
        if op == "+":
            result += num
        else:
            result -= num
    return result

