fn encrypt(s: str) -> str:
    """Rotate each lowercase letter forward by four places."""
    var out: [str] = []
    for c in s:
        if c >= "a" and c <= "z":
            code = (ord(c) - ord("a") + 4) % 26 + ord("a")
