    >>> prime_fib(2)
    3
    >>> prime_fib(3)
    5
    >>> prime_fib(4)
    13
    >>> prime_fib(5)
    89
    """
    count = 0
    a, b = 1, 2
    while True:
        if _is_prime(b):
            count += 1
            if count == n:
                return b
        a, b = b, a + b

