def valid_date(date: str) -> bool:
    """Validate a date string in the format mm-dd-yyyy."""
    if not date:
        return False
    parts = date.strip().split('-')
    if len(parts) != 3:
        return False
    mm, dd, yyyy = parts
    if not (mm.isdigit() and dd.isdigit() and yyyy.isdigit()):
        return False
    if len(mm) != 2 or len(dd) != 2 or len(yyyy) != 4:
        return False
    month, day = int(mm), int(dd)
    if month < 1 or month > 12:
        return False
    if month in (1, 3, 5, 7, 8, 10, 12):
        max_day = 31
    elif month in (4, 6, 9, 11):
        max_day = 30
    else:
        max_day = 29
    return 1 <= day <= max_day

def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    if n <= 1:
        return 1
    i: int = 2
    while i * i <= n:
        if n % i == 0:
            return n // i
        i += 1
    return 1

def file_name_check(file_name: str) -> str:
    """Return 'Yes' if the file name is valid, 'No' otherwise."""
    if file_name.count('.') != 1:
        return 'No'
    if sum(1 for c in file_name if c in '0123456789') > 3:
        return 'No'
    name, ext = file_name.split('.')
    if not name:
        return 'No'
    first = name[0]
    if not (('a' <= first <= 'z') or ('A' <= first <= 'Z')):
        return 'No'
    if ext not in ('txt', 'exe', 'dll'):
        return 'No'
    return 'Yes'

