def is_simple_power(x: int, n: int) -> bool:
    """Return True if x is n raised to some non-negative integer power."""
    if x == 1:
        return True
    if n == 1 or n == 0 or x < 1:
        return False
    if n < 0:
        # Handle negative bases by iterating powers
        p = 1
        while abs(p) < abs(x):
            p *= n
        return p == x
    p = 1
    while p < x:
        p *= n
    return p == x

