fn will_it_fly(q: [int], w: int) -> bool:
    """Return True if q is a palindrome and its sum is at most w."""
    n = len(q)
    for i in range(n // 2):
        if q[i] != q[n - 1 - i]:
            return False
    return sum(q) <= w

