def decimal_to_binary(n: int) -> str:
    """
    Write a function to convert the given decimal number to its binary equivalent, represented as a string with no leading zeros.
    """
    if n == 0:
        return "0"
    sign = "-" if n < 0 else ""
    n = abs(n)
    bits: list[str] = []
    while n > 0:
        bits.append(str(n & 1))
        n >>= 1
    return sign + "".join(reversed(bits))

